// Bundles deployments/143.json into src/config/mainnet.generated.ts (null while A hasn't committed it), so the app
// reads mainnet from the deploy record without a static import of a file that may not exist yet (C4).
// Runs before dev/build/typecheck; src/config/mainnet.test.ts fails if the generated file drifts from the record.
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

const src = fileURLToPath(new URL("../../deployments/143.json", import.meta.url));
const out = fileURLToPath(new URL("../src/config/mainnet.generated.ts", import.meta.url));
const record = existsSync(src) ? JSON.parse(readFileSync(src, "utf8")) : null;
const body = `// GENERATED by app/scripts/sync-mainnet.mjs from deployments/143.json. Do not edit.
import type { Deployment } from "./deployments";

export const MAINNET_RECORD: Deployment | null = ${JSON.stringify(record, null, 2)};
`;
writeFileSync(out, body);
console.log(`mainnet.generated.ts: ${record ? `chainId ${record.chainId}, deployed ${record.deployed !== false}` : "no deployments/143.json yet"}`);
